def _write_rzd_validation_html_response_link_discovery_inputs(
    path: Path,
    monkeypatch,
    html_body: str | bytes,
    *,
    candidate_rows: list[dict[str, object]] | None = None,
) -> dict[str, Path]:
    paths = _write_rzd_document_candidate_controlled_validation_fetch_inputs(path, monkeypatch, candidate_rows=candidate_rows)
    html_bytes = html_body.encode("utf-8") if isinstance(html_body, str) else html_body

    def validation_get(url, *, timeout_seconds, max_bytes, user_agent):
        if url.endswith("/ru/9271"):
            return {
                "status": "ok",
                "final_url": url,
                "http_status_code": 200,
                "content_type": "text/html; charset=utf-8",
                "content_disposition": "",
                "content_length_header": str(len(html_bytes)),
                "redirect_chain": [],
                "raw_bytes": html_bytes,
                "size_bytes": len(html_bytes),
            }
        body = b"\x89PNG\r\n"
        return {
            "status": "ok",
            "final_url": url,
            "http_status_code": 200,
            "content_type": "image/png",
            "content_disposition": "",
            "content_length_header": str(len(body)),
            "redirect_chain": [],
            "raw_bytes": body,
            "size_bytes": len(body),
        }

    monkeypatch.setattr(assistant, "_rzd_document_candidate_controlled_validation_http_get", validation_get)
    fetch = _run_rzd_document_candidate_controlled_validation_fetch(["--operator-resolution-chain-output-dir", str(path)])
    assert fetch["status"] in {"passed", "warning"}
    return {
        **paths,
        "task166_validation_fetch": path / "rzd_document_candidate_controlled_validation_fetch_task166.json",
        "task166_validation_fetch_results": path / "rzd_document_candidate_controlled_validation_fetch_results_task166.json",
        "task166_validation_fetch_blockers": path / "rzd_document_candidate_controlled_validation_fetch_blockers_task166.json",
        "task166_validation_fetch_hash_manifest": path / "rzd_document_candidate_controlled_validation_fetch_hash_manifest_task166.json",
    }


def _rewrite_task162_ready_rows(path: Path, ready_rows: list[dict[str, object]]) -> None:
    ready_path = path / "rzd_ranked_candidate_controlled_validation_plan_ready_task162.json"
    ready_payload = json.loads(ready_path.read_text(encoding="utf-8"))
    ready_payload["ready_candidate_rows"] = ready_rows
    ready_payload["row_count"] = len(ready_rows)
    ready_path.write_text(json.dumps(ready_payload, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")

    plan_path = path / "rzd_ranked_candidate_controlled_validation_plan_task162.json"
    plan_payload = json.loads(plan_path.read_text(encoding="utf-8"))
    plan_payload["ready_candidate_rows"] = ready_rows
    plan_payload["ready_candidate_count"] = len(ready_rows)
    plan_payload["plan_candidate_count"] = len(ready_rows)
    plan_payload["rzd_ready_for_future_controlled_candidate_page_fetch_plan"] = bool(ready_rows)
    plan_payload["rzd_ready_candidate_plan_found"] = bool(ready_rows)
    plan_payload["no_ready_validation_plan_candidates"] = not bool(ready_rows)
    plan_payload["status"] = "passed" if ready_rows else "warning"
    plan_path.write_text(json.dumps(plan_payload, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


def _write_rzd_page_link_discovery_inputs(
    path: Path,
    monkeypatch,
    *,
    html: bytes | None = None,
) -> dict[str, Path]:
    paths = _write_rzd_controlled_page_fetch_inputs(path)
    body = html or """
    <html><body>
      <a href="/ru/9471">Отчетность компании</a>
      <a href="https://company.rzd.ru/ru/9471" title="Отчетность">Отчетность компании</a>
    </body></html>
    """.encode("utf-8")

    def controlled_fetch(url, *, timeout_seconds, max_bytes, user_agent):
        assert url == assistant.RZD_EXACT_DOCUMENT_DEFAULT_URL
        return {
            "status": "ok",
            "final_url": url,
            "http_status_code": 200,
            "content_type": "text/html; charset=utf-8",
            "redirect_chain": [],
            "safe_response_headers": {"content-type": "text/html; charset=utf-8"},
            "raw_bytes": body,
        }

    monkeypatch.setattr(assistant, "_rzd_controlled_page_fetch_http_get", controlled_fetch)
    report = _run_rzd_controlled_page_fetch(_rzd_controlled_page_fetch_gate_args(paths))
    assert report["status"] in {"passed", "warning"}
    return {
        "page_fetch": path / "rzd_controlled_page_fetch_preview_task155.json",
        "links": path / "rzd_controlled_page_fetch_links_task155.json",
        "candidates": path / "rzd_controlled_page_fetch_document_candidates_task155.json",
        "manifest": path / "rzd_controlled_page_fetch_hash_manifest_task155.json",
        "plan": path / "rzd_exact_document_fetch_plan_task154.json",
        "gate": path / "exact_document_draft_gate_task137.json",
        "source_pack": path / "source_trust_recovery_controlled_source_pack_task148.json",
        "raw_html": path / "rzd_controlled_page_fetch_raw_task155.html",
    }


